with seed(standard_code,code,name,seq,required,classification,grade_code) as (values
('พ 1.1','HPE-M1-01','อธิบายความสำคัญของระบบประสาทและระบบต่อมไร้ท่อที่มีผลต่อสุขภาพ การเจริญเติบโต และพัฒนาการของวัยรุ่น',1,false,'should_know','M1'),
('พ 1.1','HPE-M1-02','อธิบายวิธีดูแลรักษาระบบประสาทและระบบต่อมไร้ท่อให้ทำงานตามปกติ',2,true,'must_know','M1'),
('พ 1.1','HPE-M1-03','วิเคราะห์ภาวะการเจริญเติบโตทางร่างกายของตนเองกับเกณฑ์มาตรฐาน',3,true,'must_know','M1'),
('พ 1.1','HPE-M1-04','แสวงหาแนวทางในการพัฒนาตนเองให้เจริญเติบโตสมวัย',4,true,'must_know','M1'),
('พ 2.1','HPE-M1-05','อธิบายวิธีการปรับตัวต่อการเปลี่ยนแปลงทางร่างกาย จิตใจ อารมณ์ และพัฒนาการทางเพศอย่างเหมาะสม',5,true,'must_know','M1'),
('พ 2.1','HPE-M1-06','แสดงทักษะการปฏิเสธเพื่อป้องกันตนเองจากการถูกล่วงละเมิดทางเพศ',6,true,'must_know','M1'),
('พ 3.1','HPE-M1-07','เพิ่มพูนความสามารถของตนตามหลักการเคลื่อนไหวที่ใช้ทักษะกลไกและทักษะพื้นฐานที่นำไปสู่การพัฒนาทักษะการเล่นกีฬา',7,true,'must_know','M1'),
('พ 3.1','HPE-M1-08','เล่นกีฬาไทยและกีฬาสากลประเภทบุคคลและทีมโดยใช้ทักษะพื้นฐานตามชนิดกีฬา อย่างละ ๑ ชนิด',8,true,'must_know','M1'),
('พ 3.1','HPE-M1-09','ร่วมกิจกรรมนันทนาการอย่างน้อย ๑ กิจกรรม และนำหลักความรู้ที่ได้ไปเชื่อมโยงสัมพันธ์กับวิชาอื่น',9,false,'should_know','M1'),
('พ 3.2','HPE-M1-10','อธิบายความสำคัญของการออกกำลังกายและเล่นกีฬา จนเป็นวิถีชีวิตที่มีสุขภาพดี',10,true,'must_know','M1'),
('พ 3.2','HPE-M1-11','ออกกำลังกายและเลือกเข้าร่วมเล่นกีฬาตามความถนัด ความสนใจ อย่างเต็มความสามารถ พร้อมทั้งมีการประเมินการเล่นของตนและผู้อื่น',11,false,'should_know','M1'),
('พ 3.2','HPE-M1-12','ปฏิบัติตามกฎ กติกา และข้อตกลง ตามชนิดกีฬาที่เลือกเล่น',12,false,'should_know','M1'),
('พ 3.2','HPE-M1-13','วางแผนการรุกและการป้องกันในการเล่นกีฬาที่เลือกและนำไปใช้ในการเล่นอย่างเป็นระบบ',13,false,'should_know','M1'),
('พ 3.2','HPE-M1-14','ร่วมมือในการเล่นกีฬาและการทำงานเป็นทีมอย่างสนุกสนาน',14,false,'should_know','M1'),
('พ 3.2','HPE-M1-15','วิเคราะห์ เปรียบเทียบ และยอมรับความแตกต่างระหว่างวิธีการเล่นกีฬาของตนเองกับผู้อื่น',15,true,'must_know','M1'),
('พ 4.1','HPE-M1-16','เลือกกินอาหารที่เหมาะสมกับวัย',16,true,'must_know','M1'),
('พ 4.1','HPE-M1-17','วิเคราะห์ปัญหาที่เกิดจากภาวะโภชนาการที่มีผลกระทบต่อสุขภาพ',17,true,'must_know','M1'),
('พ 4.1','HPE-M1-18','ควบคุมน้ำหนักของตนเองให้อยู่ในเกณฑ์มาตรฐาน',18,true,'must_know','M1'),
('พ 4.1','HPE-M1-19','สร้างเสริมและปรับปรุงสมรรถภาพทางกายตามผลการทดสอบ',19,true,'must_know','M1'),
('พ 5.1','HPE-M1-20','แสดงวิธีปฐมพยาบาลและเคลื่อนย้ายผู้ป่วยอย่างปลอดภัย',20,true,'must_know','M1'),
('พ 5.1','HPE-M1-21','อธิบายลักษณะอาการของผู้ติดสารเสพติดและการป้องกันการติดสารเสพติด',21,true,'must_know','M1'),
('พ 5.1','HPE-M1-22','อธิบายความสัมพันธ์ของการใช้สารเสพติดกับการเกิดโรคและอุบัติเหตุ',22,true,'must_know','M1'),
('พ 5.1','HPE-M1-23','แสดงวิธีการชักชวนผู้อื่นให้ลด ละ เลิกสารเสพติด โดยใช้ทักษะต่าง ๆ',23,true,'must_know','M1'),
('พ 1.1','HPE-M3-01','เปรียบเทียบการเปลี่ยนแปลงทางด้านร่างกาย จิตใจ อารมณ์ สังคมและสติปัญญาแต่ละช่วงของชีวิต',1,true,'must_know','M3'),
('พ 1.1','HPE-M3-02','วิเคราะห์อิทธิพลและความคาดหวังของสังคมต่อการเปลี่ยนแปลงของวัยรุ่น',2,false,'should_know','M3'),
('พ 1.1','HPE-M3-03','วิเคราะห์สื่อโฆษณาที่มีอิทธิพลต่อการเจริญเติบโตและพัฒนาการของวัยรุ่น',3,false,'should_know','M3'),
('พ 2.1','HPE-M3-04','อธิบายอนามัยแม่และเด็ก การวางแผนครอบครัวและวิธีการปฏิบัติตนที่เหมาะสม',4,true,'must_know','M3'),
('พ 2.1','HPE-M3-05','วิเคราะห์ปัจจัยที่มีผลกระทบต่อการตั้งครรภ์',5,true,'must_know','M3'),
('พ 2.1','HPE-M3-06','วิเคราะห์สาเหตุ และเสนอแนวทางป้องกัน แก้ไขความขัดแย้งในครอบครัว',6,false,'should_know','M3'),
('พ 3.1','HPE-M3-07','เล่นกีฬาไทยและกีฬาสากลอย่างละ ๑ ชนิด โดยใช้เทคนิคที่เหมาะสมกับตนเองและทีม',7,true,'must_know','M3'),
('พ 3.1','HPE-M3-08','นำหลักการ ความรู้ และทักษะในการเคลื่อนไหว กิจกรรมทางกาย การเล่นเกม และการเล่นกีฬาไปใช้สร้างเสริมสุขภาพอย่างต่อเนื่องเป็นระบบ',8,false,'should_know','M3'),
('พ 3.1','HPE-M3-09','ร่วมกิจกรรมนันทนาการ อย่างน้อย ๑ กิจกรรมและนำหลักความรู้วิธีการไปขยายผลการเรียนรู้ให้กับผู้อื่น',9,false,'should_know','M3'),
('พ 3.2','HPE-M3-10','มีมารยาทในการเล่นและดูกีฬาด้วยความมีน้ำใจนักกีฬา',10,false,'should_know','M3'),
('พ 3.2','HPE-M3-11','ออกกำลังกายและเล่นกีฬาอย่างสม่ำเสมอและนำแนวคิดหลักการจากการเล่นไปพัฒนาคุณภาพชีวิตของตนด้วยความภาคภูมิใจ',11,false,'should_know','M3'),
('พ 3.2','HPE-M3-12','ปฏิบัติตนตามกฎ กติกา และข้อตกลงในการเล่นตามชนิดกีฬาที่เลือกและนำแนวคิดที่ได้ไปพัฒนาคุณภาพชีวิตของตนในสังคม',12,false,'should_know','M3'),
('พ 3.2','HPE-M3-13','จำแนกกลวิธีการรุก การป้องกันและใช้ในการเล่นกีฬาที่เลือกและตัดสินใจเลือกวิธีที่เหมาะสมกับทีมไปใช้ได้ตามสถานการณ์ของการเล่น',13,false,'should_know','M3'),
('พ 3.2','HPE-M3-14','เสนอผลการพัฒนาสุขภาพของตนเองที่เกิดจากการออกกำลังกายและการเล่นกีฬาเป็นประจำ',14,false,'should_know','M3'),
('พ 4.1','HPE-M3-15','กำหนดรายการอาหารที่เหมาะสมกับวัยต่าง ๆ โดยคำนึงถึงความประหยัดและคุณค่าทางโภชนาการ',15,true,'must_know','M3'),
('พ 4.1','HPE-M3-16','เสนอแนวทางป้องกันโรคที่เป็นสาเหตุสำคัญของการเจ็บป่วยและการตายของคนไทย',16,true,'must_know','M3'),
('พ 4.1','HPE-M3-17','รวบรวมข้อมูลและเสนอแนวทางแก้ไขปัญหาสุขภาพในชุมชน',17,true,'must_know','M3'),
('พ 4.1','HPE-M3-18','วางแผนและจัดเวลาในการออกกำลังกาย การพักผ่อนและการสร้างเสริมสมรรถภาพทางกาย',18,true,'must_know','M3'),
('พ 4.1','HPE-M3-19','ทดสอบสมรรถภาพทางกายและพัฒนาได้ตามความแตกต่างระหว่างบุคคล',19,false,'should_know','M3'),
('พ 4.1','HPE-M3-20','วิเคราะห์ปัจจัยเสี่ยงและพฤติกรรมเสี่ยงที่มีผลต่อสุขภาพและแนวทางป้องกัน',20,true,'must_know','M3'),
('พ 4.1','HPE-M3-21','หลีกเลี่ยงการใช้ความรุนแรงและชักชวนเพื่อนให้หลีกเลี่ยงการใช้ความรุนแรงในการแก้ปัญหา',21,true,'must_know','M3'),
('พ 5.1','HPE-M3-22','วิเคราะห์อิทธิพลของสื่อต่อพฤติกรรมสุขภาพและความรุนแรง',22,false,'should_know','M3'),
('พ 5.1','HPE-M3-23','วิเคราะห์ความสัมพันธ์ของการดื่มเครื่องดื่มที่มีแอลกอฮอล์ต่อสุขภาพและการเกิดอุบัติเหตุ',23,true,'must_know','M3'),
('พ 5.1','HPE-M3-24','แสดงวิธีการช่วยฟื้นคืนชีพอย่างถูกวิธี',24,true,'must_know','M3')
)
insert into public.learning_objectives(topic_id,code,name,description,sequence_no,status) select t.id,s.code,s.name,null,s.seq,'active' from seed s join public.learning_subjects sub on sub.code='HEALTH-PE' join public.learning_skills sk on sk.subject_id=sub.id and sk.code='HEALTH-PE' join public.learning_topics t on t.skill_id=sk.id and t.code=s.standard_code on conflict(topic_id,code) do update set name=excluded.name,sequence_no=excluded.sequence_no,updated_at=now();
