('พ 2.1','HPE-M3-04','อธิบายอนามัยแม่และเด็ก การวางแผนครอบครัวและวิธีการปฏิบัติตนที่เหมาะสม',4,true,'must_know','M3'),
('พ 2.1','HPE-M3-05','วิเคราะห์ปัจจัยที่มีผลกระทบต่อการตั้งครรภ์',5,true,'must_know','M3'),
('พ 2.1','HPE-M3-06','วิเคราะห์สาเหตุ และเสนอแนวทางป้องกัน แก้ไขความขัดแย้งในครอบครัว',6,false,'should_know','M3'),
('พ 3.1','HPE-M3-07','เล่นกีฬาไทยและกีฬาสากลอย่างละ ๑ ชนิด โดยใช้เทคนิคที่เหมาะสมกับตนเองและทีม',7,true,'must_know','M3'),
('พ 3.1','HPE-M3-08','นำหลักการ ความรู้ และทักษะในการเคลื่อนไหว กิจกรรมทางกาย การเล่นเกม และการเล่นกีฬาไปใช้สร้างเสริมสุขภาพอย่างต่อเนื่องเป็นระบบ',8,false,'should_know','M3'),
('พ 3.1','HPE-M3-09','ร่วมกิจกรรมนันทนาการ อย่างน้อย ๑ กิจกรรมและนำหลักความรู้วิธีการไปขยายผลการเรียนรู้ให้กับผู้อื่น',9,false,'should_know','M3'),
('พ 3.2','HPE-M3-10','มีมารยาทในการเล่นและดูกีฬาด้วยความมีน้ำใจนักกีฬา',10,false,'should_know','M3'),
('พ 3.2','HPE-M3-11','ออกกำลังกายและเล่นกีฬาอย่างสม่ำเสมอและนำแนวคิดหลักการจากการเล่นไปพัฒนาคุณภาพชีวิตของตนด้วยความภาคภูมิใจ',11,false,'should_know','M3'),
('พ 3.2','HPE-M3-12','ปฏิบัติตนตามกฎ กติกา และข้อตกลงในการเล่นตามชนิดกีฬาที่เลือกและนำแนวคิดที่ได้ไปพัฒนาคุณภาพชีวิตของตนในสังคม',12,false,'should_know','M3'),
('พ 3.2','HPE-M3-13','จำแนกกลวิธีการรุก การป้องกันและใช้ในการเล่นกีฬาที่เลือกและตัดสินใจเลือกวิธีที่เหมาะสมกับทีมไปใช้ได้ตามสถานการณ์ของการเล่น',13,false,'should_know','M3'),
('พ 3.2','HPE-M3-14','เสนอผลการพัฒนาสุขภาพของตนเองที่เกิดจากการออกกำลังกายและการเล่นกีฬาเป็นประจำ',14,false,'should_know','M3'),
('พ 4.1','HPE-M3-15','กำหนดรายการอาหารที่เหมาะสมกับวัยต่าง ๆ โดยคำนึงถึงความประหยัดและคุณค่าทางโภชนาการ',15,true,'must_know','M3'),
('พ 4.1','HPE-M3-16','เสนอแนวทางป้องกันโรคที่เป็นสาเหตุสำคัญของการเจ็บป่วยและการตายของคนไทย',16,true,'must_know','M3'),
('พ 4.1','HPE-M3-17','รวบรวมข้อมูลและเสนอแนวทางแก้ไขปัญหาสุขภาพในชุมชน',17,true,'must_know','M3'),
('พ 4.1','HPE-M3-18','วางแผนและจัดเวลาในการออกกำลังกาย การพักผ่อนและการสร้างเสริมสมรรถภาพทางกาย',18,true,'must_know','M3'),
('พ 4.1','HPE-M3-19','ทดสอบสมรรถภาพทางกายและพัฒนาได้ตามความแตกต่างระหว่างบุคคล',19,false,'should_know','M3'),
('พ 4.1','HPE-M3-20','วิเคราะห์ปัจจัยเสี่ยงและพฤติกรรมเสี่ยงที่มีผลต่อสุขภาพและแนวทางป้องกัน',20,true,'must_know','M3'),
('พ 4.1','HPE-M3-21','หลีกเลี่ยงการใช้ความรุนแรงและชักชวนเพื่อนให้หลีกเลี่ยงการใช้ความรุนแรงในการแก้ปัญหา',21,true,'must_know','M3'),
('พ 5.1','HPE-M3-22','วิเคราะห์อิทธิพลของสื่อต่อพฤติกรรมสุขภาพและความรุนแรง',22,false,'should_know','M3'),
('พ 5.1','HPE-M3-23','วิเคราะห์ความสัมพันธ์ของการดื่มเครื่องดื่มที่มีแอลกอฮอล์ต่อสุขภาพและการเกิดอุบัติเหตุ',23,true,'must_know','M3'),
('พ 5.1','HPE-M3-24','แสดงวิธีการช่วยฟื้นคืนชีพอย่างถูกวิธี',24,true,'must_know','M3')
)
insert into public.learning_objective_alignments(objective_id,curriculum_id,grade_level_id,sequence_no,required,indicator_classification,notes) select o.id,c.id,g.id,s.seq,s.required,s.classification,'OBEC 2021 must-know/should-know prioritisation; official indicator wording; Thai Basic Education Core Curriculum B.E.2551.' from seed s join public.learning_subjects sub on sub.code='HEALTH-PE' join public.learning_skills sk on sk.subject_id=sub.id and sk.code='HEALTH-PE' join public.learning_topics t on t.skill_id=sk.id and t.code=s.standard_code join public.learning_objectives o on o.topic_id=t.id and o.code=s.code join public.learning_curricula c on c.id='a366b931-63be-49b5-8433-dbea2691a055' join public.learning_grade_levels g on g.curriculum_id=c.id and g.code=s.grade_code on conflict(objective_id,curriculum_id,grade_level_id) do update set sequence_no=excluded.sequence_no,required=excluded.required,indicator_classification=excluded.indicator_classification,notes=excluded.notes,updated_at=now();